<?php

declare(strict_types=1);

// Drift gate for docs/openapi.json, generated by Scramble with the API contract in app/Support/OpenApi.
//   php scripts/check-openapi.php          fail when the document, the /api route inventory, the abilities or an example drift
//   php scripts/check-openapi.php --write  regenerate docs/openapi.json (refuses an example that does not match its schema)
// Needs a migrated database: Scramble reads model columns. Keys are sorted recursively (as `jq -S`), lists keep their order.

use cebe\openapi\Reader;
use cebe\openapi\spec\OpenApi;
use cebe\openapi\spec\Schema;
use Illuminate\Contracts\Console\Kernel;
use Illuminate\Routing\Route;
use Illuminate\Routing\Router;
use Illuminate\Support\Facades\Artisan;
use Spectator\Enums\ValidationMode;
use Spectator\Exceptions\ResponseValidationException;
use Spectator\Exceptions\SchemaValidationException;
use Spectator\Validation\AbstractValidator;

require dirname(__DIR__).'/vendor/autoload.php';

// The whole gate is one boundary: Laravel's script-mode exception handler renders an uncaught exception but exits 0,
// so every failure (export, malformed committed JSON, inventory) must end here with a nonzero status.
try {
    $root = dirname(__DIR__);
    $app = require $root.'/bootstrap/app.php';
    $app->make(Kernel::class)->bootstrap();
    $app->setLocale('en');
    $committedPath = $root.'/docs/openapi.json';

    $canonical = static function (mixed $value) use (&$canonical): mixed {
        if ($value instanceof stdClass) {
            $members = get_object_vars($value);
            ksort($members, SORT_STRING);

            return (object) array_map($canonical, $members);
        }

        return is_array($value) ? array_map($canonical, $value) : $value;
    };
    $encode = static fn (mixed $document): string => json_encode($canonical($document), JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR)."\n";

    $exportPath = tempnam(sys_get_temp_dir(), 'openapi');
    // --fail-on-unknown fails on unknown schemas; the Heptapod document transformer throws on {} schemas and stale declarations.
    $status = Artisan::call('scramble:export', ['--path' => $exportPath, '--fail-on-unknown' => true]);
    $exportOutput = Artisan::output();
    $raw = file_get_contents($exportPath);
    unlink($exportPath);
    if ($status !== 0 || $raw === false) {
        fwrite(STDERR, $exportOutput.'scramble:export failed.'.PHP_EOL);
        exit(1);
    }
    $generated = $encode(json_decode($raw, flags: JSON_THROW_ON_ERROR));

    $failures = 0;
    $fail = static function (string $message) use (&$failures): void {
        fwrite(STDERR, $message.PHP_EOL);
        $failures++;
    };

    // Every example must satisfy its schema, checked with Spectator's validator (the one the API tests use) against the
    // generated document. Examples are read without cebe, which would turn an empty `{}` into a list.
    $specPath = tempnam(sys_get_temp_dir(), 'openapi');
    file_put_contents($specPath, $generated);
    $spec = Reader::readFromJsonFile($specPath);
    unlink($specPath);
    if (! $spec instanceof OpenApi) {
        throw new LogicException('The generated document is not an OpenAPI document.');
    }
    $validator = new class extends AbstractValidator
    {
        public function __construct()
        {
            $this->version = '3.1.0';
        }

        public function check(Schema $schema, mixed $value, ValidationMode $mode): void
        {
            // The JSON round trip turns keywords cebe does not model (prefixItems, OpenAPI 3.1) into schema objects.
            $this->runValidation($value, json_decode(json_encode($this->prepareData($schema, $mode), JSON_THROW_ON_ERROR), flags: JSON_THROW_ON_ERROR), ResponseValidationException::class);
        }
    };
    $document = json_decode($generated, flags: JSON_THROW_ON_ERROR);
    $examplesChecked = 0;
    foreach ($document->paths as $path => $methods) {
        foreach ($methods as $method => $operation) {
            $specOperation = $spec->paths[$path]->{$method};
            $bodies = isset($operation->requestBody) ? [['request', $operation->requestBody->content, $specOperation->requestBody->content, ValidationMode::Write]] : [];
            foreach ($operation->responses as $status => $response) {
                $bodies[] = [(string) $status, $response->content ?? new stdClass, $specOperation->responses[(string) $status]->content, ValidationMode::Read];
            }
            foreach ($bodies as [$body, $content, $specContent, $mode]) {
                foreach ($content as $mediaType => $media) {
                    $examples = property_exists($media, 'example') ? ['example' => $media->example] : [];
                    foreach ($media->examples ?? [] as $name => $example) {
                        $examples[$name] = isset($example->{'$ref'}) ? $document->components->examples->{substr($example->{'$ref'}, strlen('#/components/examples/'))}->value : $example->value;
                    }
                    foreach ($examples as $name => $value) {
                        try {
                            $validator->check($specContent[$mediaType]->schema, $value, $mode);
                            $examplesChecked++;
                        } catch (SchemaValidationException $exception) {
                            $fail('Example '.$name.' of '.strtoupper($method).' '.$path.' '.$body.' does not match its schema: '.$exception->getMessage());
                        }
                    }
                }
            }
        }
    }

    if (($argv[1] ?? null) === '--write') {
        if ($failures > 0) {
            exit(1);
        }
        file_put_contents($committedPath, $generated);
        echo 'Wrote docs/openapi.json ('.$examplesChecked.' examples match their schemas)'.PHP_EOL;
        exit(0);
    }

    $committedRaw = file_get_contents($committedPath);
    if ($committedRaw === false) {
        fwrite(STDERR, 'docs/openapi.json is missing. Run: php scripts/check-openapi.php --write'.PHP_EOL);
        exit(1);
    }
    $committed = json_decode($committedRaw, true, flags: JSON_THROW_ON_ERROR);
    if ($encode(json_decode($committedRaw, flags: JSON_THROW_ON_ERROR)) !== $generated) {
        $fail('docs/openapi.json differs from the generated document. Run: php scripts/check-openapi.php --write');
    }

    /** @var array<string, array<string, array<string, mixed>>> $paths */
    $paths = $committed['paths'];
    $operations = [];
    foreach ($paths as $path => $methods) {
        foreach ($methods as $method => $operation) {
            $operations[strtoupper($method).' '.$path] = $operation;
        }
    }
    $routes = [];
    foreach (app(Router::class)->getRoutes()->getRoutes() as $route) {
        /** @var Route $route */
        if (! str_starts_with($route->uri(), 'api/')) {
            continue;
        }
        if ($route->getName() === null) {
            $fail("Every /api route needs a name (it becomes the operationId): {$route->uri()}");
        }
        foreach (array_diff($route->methods(), ['HEAD']) as $method) {
            $routes[$method.' '.substr($route->uri(), strlen('api'))] = in_array('auth:sanctum', $route->gatherMiddleware(), true);
        }
    }
    foreach (array_diff_key($routes, $operations) as $key => $unused) {
        $fail("Route without an operation in docs/openapi.json: {$key}");
    }
    foreach (array_diff_key($operations, $routes) as $key => $unused) {
        $fail("Operation in docs/openapi.json without a route: {$key}");
    }
    foreach (array_intersect_key($routes, $operations) as $key => $protected) {
        $operation = $operations[$key];
        $abilities = $operation['x-sanctum-abilities'] ?? null;
        $named = is_array($abilities) ? [...($abilities['all'] ?? []), ...($abilities['any'] ?? [])] : [];
        if ($protected && (($operation['security'] ?? null) === [] || $named === [])) {
            $fail("Token-protected operation without bearer security and x-sanctum-abilities: {$key}");
        }
        if (! $protected && (($operation['security'] ?? null) !== [] || $abilities !== null)) {
            $fail("Public operation must declare security: [] and no abilities: {$key}");
        }
    }

    if ($failures > 0) {
        exit(1);
    }
    echo 'docs/openapi.json matches the code: '.count($operations).' operations, '.count(array_filter($routes)).' token-protected with abilities, '
        .$examplesChecked.' examples match their schemas.'.PHP_EOL;
} catch (Throwable $exception) {
    fwrite(STDERR, 'OpenAPI drift gate failed: '.$exception::class.': '.$exception->getMessage().PHP_EOL);
    exit(1);
}
